BEGIN;
CREATE TABLE bot_nodes(node_id text PRIMARY KEY,site text NOT NULL,priority integer NOT NULL DEFAULT 100 CHECK(priority>=0),enabled boolean NOT NULL DEFAULT true,draining boolean NOT NULL DEFAULT false,version text,last_heartbeat_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_nodes_eligible ON bot_nodes(enabled,draining,priority);
CREATE TABLE bot_node_capabilities(node_id text NOT NULL REFERENCES bot_nodes ON DELETE CASCADE,capability_name text NOT NULL,available boolean NOT NULL DEFAULT false,reason text,checked_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(node_id,capability_name));
CREATE TABLE bot_leases(lease_key text PRIMARY KEY,owner_node_id text REFERENCES bot_nodes ON DELETE SET NULL,generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0),acquired_at timestamptz,renewed_at timestamptz,expires_at timestamptz,CHECK(owner_node_id IS NULL OR expires_at IS NOT NULL));
CREATE INDEX ix_leases_expiry ON bot_leases(expires_at);
CREATE TABLE bot_handoff_requests(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,lease_key text NOT NULL REFERENCES bot_leases,source_node_id text REFERENCES bot_nodes,target_node_id text REFERENCES bot_nodes,expected_generation bigint NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','started','completed','failed','expired','cancelled')),requested_by text,requested_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,started_at timestamptz,completed_at timestamptz,failure_reason text);
CREATE INDEX ix_handoffs_pending ON bot_handoff_requests(lease_key,status,expires_at);
CREATE TABLE bot_runtime_settings(setting_key text NOT NULL,scope_type text NOT NULL DEFAULT 'global',scope_name text NOT NULL DEFAULT '',value_type text NOT NULL,setting_value text NOT NULL,description text,updated_by text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(setting_key,scope_type,scope_name),CHECK(value_type IN ('string','integer','boolean','duration_seconds','json')));
CREATE TABLE discord_guilds(guild_id bigint PRIMARY KEY CHECK(guild_id>0),enabled boolean NOT NULL DEFAULT true,installed_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz,removed_at timestamptz);
CREATE TABLE discord_guild_settings(guild_id bigint NOT NULL REFERENCES discord_guilds ON DELETE CASCADE,setting_key text NOT NULL,setting_value text NOT NULL,value_type text NOT NULL DEFAULT 'string',updated_by bigint,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(guild_id,setting_key),CHECK(value_type IN ('string','integer','boolean','json')));
CREATE TABLE bot_operator_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_key text NOT NULL,event_type text NOT NULL,severity text NOT NULL CHECK(severity IN ('debug','info','warning','error','critical')),active boolean NOT NULL DEFAULT true,node_id text REFERENCES bot_nodes ON DELETE SET NULL,reason text,message text NOT NULL,first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,notified_at timestamptz);
CREATE INDEX ix_events_active ON bot_operator_events(event_key,active);
CREATE INDEX ix_events_delivery ON bot_operator_events(notified_at,first_seen_at);
CREATE TABLE bot_command_metrics(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,bucket_start timestamptz NOT NULL,command_name text NOT NULL,guild_id bigint,node_id text REFERENCES bot_nodes ON DELETE SET NULL,call_count bigint NOT NULL DEFAULT 0 CHECK(call_count>=0),error_count bigint NOT NULL DEFAULT 0 CHECK(error_count>=0),duration_total_ms bigint NOT NULL DEFAULT 0 CHECK(duration_total_ms>=0),duration_max_ms integer NOT NULL DEFAULT 0 CHECK(duration_max_ms>=0));
CREATE UNIQUE INDEX uq_metrics_bucket ON bot_command_metrics(bucket_start,command_name,guild_id,node_id) NULLS NOT DISTINCT;
CREATE TABLE bot_leadership_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,lease_key text NOT NULL,event_type text NOT NULL,previous_owner_node_id text,new_owner_node_id text,previous_generation bigint,new_generation bigint,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),reason text,details jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX ix_history_time ON bot_leadership_history(lease_key,occurred_at DESC);
INSERT INTO bot_runtime_settings(setting_key,value_type,setting_value,description,updated_by) VALUES ('discord.lease_ttl_seconds','duration_seconds','30','Lease TTL','bootstrap'),('discord.lease_renew_seconds','duration_seconds','10','Lease renewal','bootstrap'),('discord.standby_poll_seconds','duration_seconds','1','Standby poll','bootstrap'),('worker.stale_after_seconds','duration_seconds','60','Heartbeat staleness','bootstrap'),('discord.db_timeout_seconds','duration_seconds','5','DB timeout','bootstrap');
INSERT INTO bot_leases(lease_key) VALUES ('discord:leader');
INSERT INTO bot_nodes(node_id,site,priority) VALUES ('rnt-01','rnt',10),('mak-01','mak',20);
CREATE TABLE alembic_version(version_num varchar(32) NOT NULL PRIMARY KEY);
INSERT INTO alembic_version VALUES ('0001_discord_initial');
COMMIT;
